+        case "down": move(1); return true;
+        case "pageup": scrollPage(-1); return true;
+        case "pagedown": scrollPage(1); return true;
+        default: return false;
+      }
+    },
+    renderTab: (_tab, target, { toolbar }) => {
+      if (toolbar === undefined) return;
+      const { controls, scroll } = toolbar;
+      const theme = getTheme();
+      const body = target as Box;
+      const field = new otui.InputRenderable(r, {
+        id: "history-search",
+        placeholder: "Search history",
+        flexGrow: 1,
+        minWidth: 4,
+        textColor: theme.text,
+        focusedTextColor: theme.text,
+        cursorColor: theme.focus,
+      });
+      const count = new otui.TextRenderable(r, { id: "history-count", fg: theme.muted, flexShrink: 0 });
+      const lifetime = new AbortController();
+      const ready = HistoryReader.open(snapshot, lifetime.signal);
+      let reader: HistoryReader | undefined;
+      let query = "";
+      let debounce: ReturnType<typeof setTimeout> | undefined;
+      let searching: AbortController | undefined;
+      let results: HistorySearch | undefined;
+      let selected = 0;
+      let selection = 0;
+      let currentMatch: Match | undefined;
+      let windowStart = 0;
+      let pendingView = 0;
+      let loadingView = false;
+      let matchingView = false;
+      let lastScrollTop = 0;
+      let afterLayout: (() => void) | undefined;
+      type Row = { view: InstanceType<OpenTui["TextRenderable"]>; index: number; entry: number; start: number; text: string };
+      let rows: Row[] = [];
+      const hint = (content: string): void => {
+        body.add(new otui.TextRenderable(r, { content, fg: theme.muted, flexShrink: 0 }));
+      };
+      hint("Loading history…");
+
+      const overlaps = (row: Row, match: Match | undefined): match is Match =>
+        match?.entry === row.entry && match.end > row.start && match.start < row.start + row.text.length;
+      const mark = (row: Row, match: Match | undefined): void => {
+        if (!overlaps(row, match)) {
+          row.view.content = row.text;
+          return;
+        }
+        const start = Math.max(0, match.start - row.start);
+        const end = match.end - row.start;
+        const highlighted = otui.bg(theme.focus)(otui.fg(theme.panel)(row.text.slice(start, end)));
+        row.view.content = otui.t`${row.text.slice(0, start)}${highlighted}${row.text.slice(end)}`;
+      };
+      const repaintMatch = (match: Match | undefined): void => {
+        for (const row of rows) {
+          if (overlaps(row, currentMatch) || overlaps(row, match)) mark(row, match);
+        }
+        currentMatch = match;
+      };
+      const scrollToMatch = (match: Match): void => {
+        const row = rows.find((item) => item.index === match.fragment);
+        if (row === undefined) return;
+        const prefix = row.text.slice(0, match.start - row.start).split("\n");
+        const sourceLine = prefix.length - 1;
+        const column = Bun.stringWidth(prefix[sourceLine]!);
+        const { lineSources, lineStartCols } = row.view.lineInfo;
+        let visualLine = Math.max(0, lineSources.indexOf(sourceLine));
+        const startColumn = lineStartCols[visualLine] ?? 0;
+        while (lineSources[visualLine + 1] === sourceLine
+          && lineStartCols[visualLine + 1]! - startColumn <= column) visualLine++;
+        scroll.scrollTop += row.view.y - scroll.viewport.y + visualLine;
+      };
+      const maxStart = (): number => Math.max(0, (reader?.length ?? 0) - PAGE);
+      const showWindow = async (start: number, position: "end" | "anchor" | Match): Promise<void> => {
+        if (reader === undefined) return;
+        const request = ++pendingView;
+        loadingView = true;
+        matchingView = typeof position !== "string";
+        afterLayout = undefined;
+        try {
+          const page = await reader.page(start, Math.min(start + PAGE, reader.length), lifetime.signal);
+          if (request !== pendingView || lifetime.signal.aborted) return;
+          const anchor = position === "anchor"
+            ? rows.find((row) => row.index >= start && row.index < start + PAGE
+              && row.view.y + row.view.height > scroll.viewport.y)
+            : undefined;
+          const anchorY = anchor === undefined ? 0 : anchor.view.y - scroll.viewport.y;
+          clearTranscriptChildren(body);
+          rows = page.map(({ index, entry, start: offset, label, text }) => {
+            if (label !== "") {
+              body.add(new otui.TextRenderable(r, {
+                content: otui.t`${boldChunk(otui, label)}`,
+                marginTop: index === start ? 0 : 1,
+                flexShrink: 0,
+              }));
+            }
+            const view = new otui.TextRenderable(r, {
+              id: `history-entry-${index}`, content: text, fg: theme.text,
+              width: "100%", wrapMode: "word", flexShrink: 0,
+            });
+            body.add(view);
+            const row = { view, index, entry, start: offset, text };
+            if (overlaps(row, currentMatch)) mark(row, currentMatch);
+            return row;
+          });
+          if (page.length === 0) hint("This session has no messages yet.");
+          const shiftedEarlier = start < windowStart;
+          windowStart = start;
+          afterLayout = () => {
+            if (position === "end") scroll.scrollTop = scroll.scrollHeight;
+            else if (typeof position !== "string") scrollToMatch(position);
+            else if (anchor !== undefined) {
+              const view = rows.find((row) => row.index === anchor.index)!.view;
+              scroll.scrollTop += view.y - scroll.viewport.y - anchorY;
+            } else {
+              scroll.scrollTop = shiftedEarlier ? scroll.scrollHeight : 0;
+            }
+            loadingView = false;
+            matchingView = false;
+          };
+          r.requestRender();
+        } catch {
+          if (lifetime.signal.aborted || request !== pendingView) return;
+          loadingView = false;
+          matchingView = false;
+          count.content = " History unavailable";
+        }
+      };
+      const shiftWindow = (direction: number): void => {
+        if (loadingView || reader === undefined) return;
+        const top = scroll.scrollTop;
+        const bottom = Math.max(0, scroll.scrollHeight - scroll.viewport.height);
+        if (direction < 0 && top <= 2 && windowStart > 0) {
+          void showWindow(Math.max(0, windowStart - PAGE / 2), "anchor");
+        } else if (direction > 0 && top >= bottom - 2 && windowStart < maxStart()) {
+          void showWindow(Math.min(maxStart(), windowStart + PAGE / 2), "anchor");
+        }
+      };
+      const frame = (): void => {
+        if (afterLayout !== undefined) {
+          const position = afterLayout;
+          afterLayout = undefined;
+          position();
+          lastScrollTop = scroll.scrollTop;
+          return;
+        }
+        const current = scroll.scrollTop;
+        shiftWindow(Math.sign(current - lastScrollTop));
+        lastScrollTop = current;
+      };
+      r.on(otui.CliRenderEvents.FRAME, frame);
+      scroll.onMouseScroll = (event) => {
+        const direction = event.scroll?.direction;
+        if (direction === "up" || direction === "down") {
+          queueMicrotask(() => {
+            if (!lifetime.signal.aborted) shiftWindow(direction === "up" ? -1 : 1);
+          });
+        }
+      };
+      const scrollBy = (delta: number): void => {
+        scroll.scrollBy(delta);
+        shiftWindow(Math.sign(delta));
+      };
+
+      const showMatch = async (): Promise<void> => {
+        const result = results;
+        const signal = searching?.signal;
+        if (result === undefined || signal === undefined || result.total === 0) return;
+        const request = ++selection;
+        const ordinal = selected;
+        try {
+          const match = await result.locate(ordinal, signal);
+          if (match === undefined || signal.aborted || request !== selection) return;
+          count.content = ` ${ordinal + 1}/${result.total}`;
+          repaintMatch(match);
+          if (loadingView || match.fragment < windowStart || match.fragment >= windowStart + rows.length) {
+            await showWindow(Math.max(0, Math.min(maxStart(), match.fragment - PAGE / 2)), match);
+          } else {
+            afterLayout = () => {
+              if (!signal.aborted && request === selection) scrollToMatch(match);
+            };
+            r.requestRender();
+          }
+        } catch {
+          if (!signal.aborted && request === selection) count.content = " Search unavailable";
+        }
+      };
+      const runSearch = async (): Promise<void> => {
+        debounce = undefined;
+        const request = new AbortController();
+        searching = request;
+        try {
+          const source = await ready;
+          request.signal.throwIfAborted();
+          const result = await source.search(query, request.signal);
+          request.signal.throwIfAborted();
+          results = result;
+          if (result.total === 0) count.content = " No matches";
+          else void showMatch();
+        } catch {
+          if (!request.signal.aborted && !lifetime.signal.aborted) count.content = " Search unavailable";
+        }
+      };
+      const updateQuery = (): void => {
+        const next = field.value.trim();
+        if (next === query) return;
+        query = next;
+        clearTimeout(debounce);
+        debounce = undefined;
+        searching?.abort();
+        results = undefined;
+        selected = 0;
+        // A delayed jump for the previous query may still be reading from disk.
+        if (matchingView) {
+          pendingView++;
+          loadingView = false;
+          matchingView = false;
+          afterLayout = undefined;
+        }
+        repaintMatch(undefined);
+        count.content = query === "" ? "" : " Searching…";
+        if (query !== "") debounce = setTimeout(() => { void runSearch(); }, 45);
+      };
+      const submit = (): void => {
+        updateQuery();
+        if (debounce !== undefined) {
+          clearTimeout(debounce);
+          void runSearch();
+        } else {
+          void showMatch();
+        }
+        field.focus();
+      };
+      controls.add(field);
+      controls.add(new otui.TextRenderable(r, {
+        id: "history-find",
+        content: " [Find]",
+        fg: theme.focus,
+        flexShrink: 0,
+        onMouseDown: (event) => {
+          event.preventDefault();
+          event.stopPropagation();
+          submit();
+        },
+      }));
+      controls.add(count);
+      field.on(otui.InputRenderableEvents.INPUT, updateQuery);
+      field.on(otui.InputRenderableEvents.ENTER, submit);
+      field.focus();
+      move = (delta) => {
+        if (results === undefined || results.total === 0) scrollBy(delta);
+        else {
+          selected = (selected + delta + results.total) % results.total;
+          void showMatch();
+        }
+      };
+      scrollPage = (delta) => scrollBy(delta * Math.max(1, scroll.viewport.height - 1));
+
+      void ready.then((source) => {
+        if (lifetime.signal.aborted) return;
+        reader = source;
+        void showWindow(maxStart(), "end");
+      }).catch(() => {
+        if (lifetime.signal.aborted) return;
+        clearTranscriptChildren(body);
+        hint("History unavailable.");
+      });
+      return () => {
+        lifetime.abort();
+        clearTimeout(debounce);
+        searching?.abort();
+        scroll.onMouseScroll = undefined;
+        r.off(otui.CliRenderEvents.FRAME, frame);
+        void ready.then((source) => source.close()).catch(() => {});
+      };
+    },
+  });
+}

+import { expect, test } from "bun:test";
+import { mkdtempSync, renameSync, rmSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import path from "node:path";
+import type { NormalizedMessage } from "../harness/provider/types";
+import { HistoryReader, historySnapshot } from "./history-reader";
+
+test("search counts millions of hits and locates the last one without retaining each hit", async () => {
+  const directory = mkdtempSync(path.join(tmpdir(), "keryx-history-reader-"));
+  const content = "a ".repeat(2048);
+  const messages: NormalizedMessage[] = Array.from({ length: 2048 }, () => ({ role: "assistant", content }));
+  const file = path.join(directory, "archive.jsonl");
+  writeFileSync(file, (JSON.stringify(messages[0]) + "\n").repeat(messages.length));
+  const signal = new AbortController().signal;
+  try {
+    const reader = await HistoryReader.open(historySnapshot(messages, [], directory), signal);
+    try {
+      const cancelled = new AbortController();
+      const interrupted = reader.search("a", cancelled.signal);
+      setTimeout(() => cancelled.abort(), 5);
+      await expect(interrupted).rejects.toThrow();
+
+      const search = await reader.search("A", signal);
+      expect(search.total).toBe(4_194_304);
+      expect(await search.locate(search.total - 1, signal)).toEqual({ entry: 2047, fragment: 2047, start: 4094, end: 4095 });
+      expect(await search.locate(1024, signal)).toEqual({ entry: 0, fragment: 0, start: 2048, end: 2049 });
+    } finally {
+      await reader.close();
+    }
+  } finally {
+    rmSync(directory, { recursive: true, force: true });
+  }
+}, 15_000);
+
+test("uses the selected checkpoint and live tail when the disk mirror is stale or replaced", async () => {
+  const directory = mkdtempSync(path.join(tmpdir(), "keryx-history-mirror-"));
+  const archive: NormalizedMessage[] = [
+    { role: "user", content: "Saved [literal]" },
+    { role: "assistant", content: "Selected checkpoint" },
+  ];
+  const tail: NormalizedMessage = { role: "assistant", content: "Unflushed answer" };
+  const file = path.join(directory, "archive.jsonl");
+  writeFileSync(file, JSON.stringify(archive[0]) + "\n" + JSON.stringify({ ...archive[1], content: "Stale mirror" }) + "\n");
+  const signal = new AbortController().signal;
+  try {
+    const snapshot = historySnapshot(archive, [tail], directory);
+    tail.content += " changed";
+    const reader = await HistoryReader.open(snapshot, signal);
+    try {
+      renameSync(file, path.join(directory, "old.jsonl"));
+      writeFileSync(file, "");
+      expect((await reader.page(0, reader.length, signal)).map((row) => row.text)).toEqual([
+        "Saved [literal]", "Selected checkpoint", "Unflushed answer",
+      ]);
+      expect((await reader.search("[literal]", signal)).total).toBe(1);
+      expect((await reader.search("stale", signal)).total).toBe(0);
+    } finally {
+      await reader.close();
+    }
+  } finally {
+    rmSync(directory, { recursive: true, force: true });
+  }
+});
+
+test("can page across a single large message and jump to a match spanning fragments", async () => {
+  const content = "x".repeat(4095) + "Needle" + "🦊".repeat(3000);
+  const signal = new AbortController().signal;
+  const reader = await HistoryReader.open(historySnapshot([{ role: "assistant", content }]), signal);
+  try {
+    expect(reader.length).toBe(3);
+    const page = await reader.page(0, reader.length, signal);
+    expect(page.map((row) => row.text).join("")).toBe(content);
+    expect(page.every((row) => row.text.length <= 4096)).toBe(true);
+    const search = await reader.search("needle", signal);
+    expect(await search.locate(0, signal)).toEqual({ entry: 0, fragment: 0, start: 4095, end: 4101 });
+  } finally {
+    await reader.close();
+  }
+});
+
+test("finds the final fragment of a multi-megabyte line without requiring a newline", async () => {
+  const prefix = "x".repeat(8 * 1024 * 1024);
+  const signal = new AbortController().signal;
+  const reader = await HistoryReader.open(historySnapshot([{ role: "assistant", content: prefix + "Last hit" }]), signal);
+  try {
+    const last = reader.length - 1;
+    const page = await reader.page(last - 1, reader.length, signal);
+    expect(page.map(({ start, text }) => [start, text.length])).toEqual([
+      [prefix.length - 4096, 4096], [prefix.length, "Last hit".length],
+    ]);
+    const search = await reader.search("Last hit", signal);
+    expect(await search.locate(0, signal)).toEqual({
+      entry: 0, fragment: last, start: prefix.length, end: prefix.length + "Last hit".length,
+    });
+  } finally {
+    await reader.close();
+  }
+});

+import { constants } from "node:fs";
+import { open, type FileHandle } from "node:fs/promises";
+import path from "node:path";
+import type { NormalizedMessage } from "../harness/provider/types";
+import { MAX_TRANSCRIPT_FILE_BYTES } from "../lib/config-dir";
+import { conversationEntry, type ConversationEntry } from "./conversation-history";
+
+const READ_BYTES = 64 * 1024;
+const FRAGMENT_CHARS = 4096;
+const MATCH_STRIDE = 1024;
+
+export type HistorySnapshot = { messages: readonly NormalizedMessage[]; directory?: string };
+type Fragment = { entry: number; start: number; end: number };
+type IndexedEntry = { message: number; first: number; end: number };
+type MatchGroup = { entry: number; first: number; checkpoints: number[] };
+type Match = { entry: number; fragment: number; start: number; end: number };
+export type HistorySearch = { total: number; locate(index: number, signal: AbortSignal): Promise<Match | undefined> };
+
+async function yieldToInput(signal: AbortSignal): Promise<void> {
+  await Bun.sleep(0);
+  signal.throwIfAborted();
+}
+
+/** The compatibility mirror is atomically replaced. Pin its inode for the lifetime of the window. */
+class ArchiveLines {
+  private offsets = [0];
+  private block: { position: number; bytes: Promise<Buffer> } | undefined;
+
+  private constructor(private readonly file: FileHandle, private readonly size: number) {}
+
+  static async open(directory: string, count: number, signal: AbortSignal): Promise<ArchiveLines | undefined> {
+    let file: FileHandle | undefined;
+    try {
+      file = await open(path.join(directory, "archive.jsonl"), constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
+      const stat = await file.stat();
+      if (!stat.isFile() || stat.size === 0 || stat.size > MAX_TRANSCRIPT_FILE_BYTES) {
+        await file.close();
+        return;
+      }
+      const lines = new ArchiveLines(file, stat.size);
+      for (let position = 0; position < stat.size && lines.offsets.length <= count; position += READ_BYTES) {
+        signal.throwIfAborted();
+        const bytes = await lines.read(position, Math.min(READ_BYTES, stat.size - position));
+        for (let newline = bytes.indexOf(10); newline >= 0; newline = bytes.indexOf(10, newline + 1)) {
+          lines.offsets.push(position + newline + 1);
+          if (lines.offsets.length > count) break;
+        }
+      }
+      if (lines.offsets.at(-1)! < stat.size) lines.offsets.push(stat.size);
+      return lines;
+    } catch {
+      await file?.close().catch(() => {});
+      signal.throwIfAborted();
+      // An unavailable mirror is normal for legacy sessions and interrupted checkpoints.
+      return undefined;
+    }
+  }
+
+  async close(): Promise<void> { await this.file.close(); }
+
+  private async read(position: number, length: number): Promise<Buffer> {
+    const bytes = Buffer.allocUnsafe(length);
+    for (let offset = 0; offset < length;) {
+      const { bytesRead } = await this.file.read(bytes, offset, length - offset, position + offset);
+      if (bytesRead === 0) throw new Error("History archive ended before the indexed line");
+      offset += bytesRead;
+    }
+    return bytes;
+  }
+
+  async message(index: number, expected: NormalizedMessage): Promise<NormalizedMessage> {
+    const start = this.offsets[index];
+    const end = this.offsets[index + 1];
+    if (start === undefined || end === undefined || end <= start) return expected;
+    try {
+      const position = Math.floor(start / READ_BYTES) * READ_BYTES;
+      let line: Buffer;
+      if (end - position <= READ_BYTES) {
+        if (this.block?.position !== position) {
+          this.block = { position, bytes: this.read(position, Math.min(READ_BYTES, this.size - position)) };
+        }
+        line = (await this.block.bytes).subarray(start - position, end - position);
+      } else {
+        line = await this.read(start, end - start);
+      }
+      const saved = JSON.parse(line.toString("utf8")) as NormalizedMessage | null;
+      // The selected preservation checkpoint is authoritative, even if its mirror
+      // was interrupted. Fall back per row, including unsaved or growing replies.
+      if (saved?.role === expected.role && saved.content === expected.content
+        && saved.provenance === expected.provenance && saved.injected === expected.injected) return saved;
+    } catch {
+      // A damaged mirror must not hide the already validated session history.
+    }
+    return expected;
+  }
+}
+
+export function historySnapshot(archive: readonly NormalizedMessage[], tail: readonly NormalizedMessage[] = [], directory?: string): HistorySnapshot {
+  const messages = [...archive, ...tail];
+  // The foreground stream can still extend the last assistant message in place.
+  const last = messages.at(-1);
+  if (last?.role === "assistant") messages[messages.length - 1] = { ...last };
+  return { messages, ...(directory === undefined ? {} : { directory }) };
+}
+
+export class HistoryReader {
+  private readonly entries: IndexedEntry[] = [];
+  private readonly fragments: Fragment[] = [];
+
+  private constructor(private readonly snapshot: HistorySnapshot, private readonly file?: ArchiveLines) {}
+
+  static async open(snapshot: HistorySnapshot, signal: AbortSignal): Promise<HistoryReader> {
+    const file = snapshot.directory === undefined ? undefined : await ArchiveLines.open(snapshot.directory, snapshot.messages.length, signal);
+    const history = new HistoryReader(snapshot, file);
+    try {
+      for (let index = 0; index < snapshot.messages.length; index++) {
+        if (index % 128 === 0) await yieldToInput(signal);
+        const entry = conversationEntry(snapshot.messages[index]!);
+        if (entry === undefined) continue;
+        const first = history.fragments.length;
+        for (let start = 0; start < entry.text.length;) {
+          let end = Math.min(start + FRAGMENT_CHARS, entry.text.length);
+          if (end < entry.text.length) {
+            // A long line may have no newline at all. Only scan the part of
+            // this fragment where a break could actually change the split.
+            const searchFrom = start + FRAGMENT_CHARS / 2 + 1;
+            const newline = entry.text.slice(searchFrom, end).lastIndexOf("\n");
+            if (newline >= 0) end = searchFrom + newline + 1;
+            const code = entry.text.charCodeAt(end);
+            if (code >= 0xdc00 && code <= 0xdfff) end--;
+          }
+          history.fragments.push({ entry: history.entries.length, start, end });
+          start = end;
+        }
+        history.entries.push({ message: index, first, end: history.fragments.length });
+      }
+      signal.throwIfAborted();
+      return history;
+    } catch (error) {
+      await history.close();
+      throw error;
+    }
+  }
+
+  get length(): number { return this.fragments.length; }
+  async close(): Promise<void> { await this.file?.close(); }
+
+  private async entry(index: number): Promise<ConversationEntry> {
+    const messageIndex = this.entries[index]!.message;
+    const expected = this.snapshot.messages[messageIndex]!;
+    const message = this.file === undefined ? expected : await this.file.message(messageIndex, expected);
+    return conversationEntry(message)!;
+  }
+
+  async page(start: number, end: number, signal: AbortSignal): Promise<Array<ConversationEntry & { index: number; entry: number; start: number }>> {
+    const rows: Array<ConversationEntry & { index: number; entry: number; start: number }> = [];
+    let last = -1;
+    let entry: ConversationEntry | undefined;
+    for (let index = start; index < end; index++) {
+      signal.throwIfAborted();
+      const fragment = this.fragments[index]!;
+      if (last !== fragment.entry) {
+        entry = await this.entry(fragment.entry);
+        last = fragment.entry;
+      }
+      rows.push({
+        index, entry: fragment.entry, start: fragment.start,
+        label: fragment.start === 0 ? entry!.label : "", text: entry!.text.slice(fragment.start, fragment.end),
+      });
+    }
+    return rows;
+  }
+
+  async search(needle: string, signal: AbortSignal): Promise<HistorySearch> {
+    if (needle === "") return { total: 0, locate: async () => undefined };
+    const literal = needle.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
+    const pattern = new RegExp(literal, "giu");
+    const groups: MatchGroup[] = [];
+    let total = 0;
+    for (let index = 0; index < this.entries.length; index++) {
+      if (index % 64 === 0) await yieldToInput(signal);
+      const { text } = await this.entry(index);
+      const first = total;
+      const checkpoints: number[] = [];
+      pattern.lastIndex = 0;
+      for (let hit = pattern.exec(text); hit !== null; hit = pattern.exec(text)) {
+        if ((total - first) % MATCH_STRIDE === 0) checkpoints.push(hit.index);
+        total++;
+        if (total % 8192 === 0) await yieldToInput(signal);
+      }
+      if (total > first) groups.push({ entry: index, first, checkpoints });
+    }
+    return {
